src/Infrastructure/
├── Doctrine/
│   ├── Entity/
│   │   ├── OrderEntity.php           # mapped class
│   │   ├── OrderLineEntity.php
│   │   ├── CustomerEntity.php
│   │   └── ProductEntity.php
│   ├── Repository/
│   │   ├── DoctrineOrderRepository.php  # реализация OrderRepository
│   │   ├── DoctrineCustomerRepository.php
│   │   └── DoctrineProductRepository.php
